-- Ownership/RLS and table write revocations from 005 remain unchanged.
create function public.chess_v1_content(p_date date,p_difficulty text) returns jsonb language sql immutable set search_path='' as $$
 select entry from jsonb_array_elements('/* CHESS_MANIFEST */'::jsonb) entry
 where entry->>'difficulty'=p_difficulty and (entry->>'index')::integer=mod(mod(p_date-date '1970-01-01',2)+2,2)
$$;
create function public.validate_chess_v1(p_date date,p_difficulty text,p_state jsonb) returns void language plpgsql immutable set search_path='' as $$
declare content jsonb;path jsonb;event jsonb;ids uuid[]:='{}';event_id uuid;count_moves integer;compatible boolean:=false;matches boolean;i integer;
begin
 content:=public.chess_v1_content(p_date,p_difficulty);
 if content is null or p_date is null or p_date<date '0001-01-01' or p_date>date '9999-12-31' or p_state is null or jsonb_typeof(p_state)<>'object'
 or not(p_state ?& array['puzzleId','moves','events']) or p_state-array['puzzleId','moves','events']<>'{}'::jsonb
 or p_state->>'puzzleId' is distinct from content->>'id' or jsonb_typeof(p_state->'moves')<>'array' or jsonb_typeof(p_state->'events')<>'array'
 then raise exception 'Invalid chess identity/state' using errcode='22023';end if;
 count_moves:=jsonb_array_length(p_state->'moves');
 for path in select value from jsonb_array_elements(content->'paths') loop
  if count_moves<=jsonb_array_length(path) then
   matches:=true;
   if count_moves>0 then for i in 0..count_moves-1 loop if p_state->'moves'->i<>path->i then matches:=false;end if;end loop;end if;
   compatible:=compatible or matches;
  end if;
 end loop;
 if not compatible or jsonb_array_length(p_state->'events')>2000 then raise exception 'Invalid chess solution or too many events' using errcode='22023';end if;
 for event in select value from jsonb_array_elements(p_state->'events') loop
  if jsonb_typeof(event)<>'object' or not(event ?& array['id','kind','ply']) or event-array['id','kind','ply','move']<>'{}'::jsonb
  or jsonb_typeof(event->'id')<>'string' or jsonb_typeof(event->'kind')<>'string' or event->>'kind' not in ('hint','mistake')
  or jsonb_typeof(event->'ply')<>'number' or (event->>'ply')!~'^[0-9]+$'
  then raise exception 'Invalid chess event' using errcode='22023';end if;
  event_id:=(event->>'id')::uuid;
  if event_id=any(ids) or (event->>'ply')::integer>count_moves then raise exception 'Duplicate or future chess event' using errcode='22023';end if;
  -- Events must refer to an unfinished player turn, never after a terminal solve.
  for path in select value from jsonb_array_elements(content->'paths') loop
   if (event->>'ply')::integer>=jsonb_array_length(path) then
    matches:=true;
    for i in 0..jsonb_array_length(path)-1 loop if p_state->'moves'->i is distinct from path->i then matches:=false;end if;end loop;
    if matches then raise exception 'Event after solve' using errcode='22023';end if;
   end if;
  end loop;
  if event->>'kind'='mistake' then
   if jsonb_typeof(event->'move') is distinct from 'string' or (event->>'move')!~'^[a-h][1-8][a-h][1-8][qrbn]?$' then raise exception 'Invalid attempted move' using errcode='22023';end if;
  elsif event ? 'move' then raise exception 'Hints do not contain moves' using errcode='22023';end if;
  ids:=array_append(ids,event_id);
 end loop;
end $$;
create function public.submit_chess_progress(p_operation_id uuid,p_date date,p_difficulty text,p_state jsonb)
returns void language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid();saved public.game_progress;receipt jsonb;payload jsonb;merged jsonb;old_count integer;new_count integer;i integer;event jsonb;previous jsonb;events jsonb;
begin
 if actor is null then raise exception 'Sign in first' using errcode='42501';end if;
 if p_operation_id is null then raise exception 'Operation ID required' using errcode='22023';end if;
 perform public.validate_chess_v1(p_date,p_difficulty,p_state);
 payload:=jsonb_build_object('kind','chess','date',p_date,'difficulty',p_difficulty,'state',p_state);
 perform pg_advisory_xact_lock(hashtextextended('game:'||actor::text,0));
 select o.payload into receipt from public.game_write_operations o where user_id=actor and operation_id=p_operation_id;
 if found then if receipt<>payload then raise exception 'Operation ID reused' using errcode='22023';end if;return;end if;
 select * into saved from public.game_progress where user_id=actor and game_id='chess' and puzzle_version=1 and puzzle_date=p_date and difficulty=p_difficulty;
 merged:=p_state;
 if found then
  old_count:=jsonb_array_length(saved.state->'moves');new_count:=jsonb_array_length(p_state->'moves');
  if least(old_count,new_count)>0 then for i in 0..least(old_count,new_count)-1 loop
   if saved.state->'moves'->i<>p_state->'moves'->i then raise exception 'Different chess branches; both preserved' using errcode='40001';end if;
  end loop;end if;
  events:=saved.state->'events';
  for event in select value from jsonb_array_elements(p_state->'events') loop
   select value into previous from jsonb_array_elements(events) where value->>'id'=event->>'id';
   if found then if previous<>event then raise exception 'Different chess event' using errcode='40001';end if;
   else events:=events||jsonb_build_array(event);end if;
  end loop;
  select coalesce(jsonb_agg(value order by value->>'id'),'[]') into events from jsonb_array_elements(events);
  merged:=jsonb_build_object('puzzleId',p_state->'puzzleId','moves',case when old_count>new_count then saved.state->'moves' else p_state->'moves' end,'events',events);
  perform public.validate_chess_v1(p_date,p_difficulty,merged);
  if merged<>saved.state then update public.game_progress set state=merged,revision=revision+1,updated_at=now() where user_id=actor and game_id='chess' and puzzle_version=1 and puzzle_date=p_date and difficulty=p_difficulty;end if;
 else
  insert into public.game_progress(user_id,game_id,puzzle_version,puzzle_date,difficulty,state) values(actor,'chess',1,p_date,p_difficulty,p_state);
 end if;
 insert into public.game_write_operations(user_id,operation_id,payload) values(actor,p_operation_id,payload);
end $$;
